let results = [];

for (const item of $input.all()) {
  if (!item.binary) continue;

  const meta = {
    subject: item.json?.subject,
    from: item.json?.from,
    to: item.json?.to,
    date: item.json?.date,
    messageId: item.json?.messageId,
    delivered_to: item.json?.headers?.["delivered-to"] || "",
        body_text: item.json?.text || "",
    combined_email_text:
      (item.json?.subject || "") +
      (item.json?.text || "") +
      (item.json?.html || ""),
  };

  for (const key of Object.keys(item.binary)) {
    results.push({
      json: {
        ...meta,
        attachment_key: key,
        fileName: item.binary[key]?.fileName,
        mimeType: item.binary[key]?.mimeType,
      },
      binary: {
        data: item.binary[key],   // IMPORTANT: always use one fixed name: "data"
      },
    });
  }
}

return results;

