const items = $input.all();

function stripFences(s) {
  return String(s || "")
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/g, "")
    .trim();
}

const requiredKeys = [
  "candidate_name",
  "candidate_phone",
  "candidate_email",
  "match_score",
  "summary",
  "missing_skills",
  "score_skills",
  "score_experience",
  "score_education",
  "score_certifications",
  "score_soft_skills",
  "score_domain_knowledge",
  "score_other_requirements",
];

return items.map((item) => {
  try {
    const rawText = item.json.output?.[0]?.content?.[0]?.text;
    if (!rawText) throw new Error("Missing OpenAI output text at item.json.output[0].content[0].text");

    const clean = stripFences(rawText);
    const data = JSON.parse(clean);

    // Basic key validation
    for (const k of requiredKeys) {
      if (!(k in data)) throw new Error(`Missing required key: ${k}`);
    }

    // Ensure missing_skills is array
    if (!Array.isArray(data.missing_skills)) data.missing_skills = [];

    // match_score must be null here (as per our prompt)
    // if model returns a number, we still accept but overwrite in calc node
    return { json: data };
  } catch (e) {
    return {
      json: {
        error: "LLM JSON parse/validation failed",
        message: e.message,
        original: item.json,
      },
    };
  }
});

const items = $input.all();
const jd = $node["JOB Description"].json;

function toNum(v, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}
function clamp0to100(v) {
  const n = Math.round(toNum(v, 0));
  return Math.max(0, Math.min(100, n));
}

const weights = {
  skills: toNum(jd.weight_skills, 0),
  experience: toNum(jd.weight_experience, 0),
  education: toNum(jd.weight_education, 0),
  certifications: toNum(jd.weight_certifications, 0),
  soft_skills: toNum(jd.weight_soft_skills, 0),
  domain_knowledge: toNum(jd.weight_domain_knowledge, 0),
  other_requirements: toNum(jd.weight_other_requirements, 0),
};

return items.map((item) => {
  const j = item.json;
  if (j.error) return item;

  const scores = {
    skills: clamp0to100(j.score_skills),
    experience: clamp0to100(j.score_experience),
    education: clamp0to100(j.score_education),
    certifications: clamp0to100(j.score_certifications),
    soft_skills: clamp0to100(j.score_soft_skills),
    domain_knowledge: clamp0to100(j.score_domain_knowledge),
    other_requirements: clamp0to100(j.score_other_requirements),
  };

  const matchScore =
    (scores.skills * weights.skills) / 100 +
    (scores.experience * weights.experience) / 100 +
    (scores.education * weights.education) / 100 +
    (scores.certifications * weights.certifications) / 100 +
    (scores.soft_skills * weights.soft_skills) / 100 +
    (scores.domain_knowledge * weights.domain_knowledge) / 100 +
    (scores.other_requirements * weights.other_requirements) / 100;

  j.match_score = Math.round(matchScore);
  return { json: j };
});
